    {
      "qualname": "arrow/arrow.py::Arrow.dehumanize",
      "source": "def dehumanize(self, timestring: str, locale: str = "en_us") -> "Arrow":
    """Returns a new :class:`Arrow <arrow.arrow.Arrow>` object, that represents
    the time difference relative to the attrbiutes of the
    :class:`Arrow <arrow.arrow.Arrow>` object.

    :param timestring: a ``str`` representing a humanized relative time.
    :param locale: (optional) a ``str`` specifying a locale.  Defaults to 'en-us'.

    Usage::

            >>> arw = arrow.utcnow()
            >>> arw
            <Arrow [2021-04-20T22:27:34.787885+00:00]>
            >>> earlier = arw.dehumanize("2 days ago")
            >>> earlier
            <Arrow [2021-04-18T22:27:34.787885+00:00]>

            >>> arw = arrow.utcnow()
            >>> arw
            <Arrow [2021-04-20T22:27:34.787885+00:00]>
            >>> later = arw.dehumanize("in a month")
            >>> later
            <Arrow [2021-05-18T22:27:34.787885+00:00]>

    """

    l = locales.get_locale(locale)
    nln = locale.lower().replace("_", "-")
    if nln not in DEHUMANIZE_LOCALES:
        raise ValueError(
            f"Dehumanize does not currently support the {locale} locale, please consider making a contribution to add support for this locale."
        )
    ct = self.fromdatetime(self._datetime)
    info = dict.fromkeys(["seconds", "minutes", "hours", "days", "weeks", "months", "years"], 0)
    visited = dict.fromkeys(["now", "seconds", "minutes", "hours", "days", "weeks", "months", "years"], False)
    num_pat = re.compile(r"\d+")
    for unit in l.timeframes:
        cv = 0
        ss = str(l.timeframes[unit]).format(r"\d+")
        m = re.compile(fr"{ss}").search(timestring)
        if not m:
            continue
        ms = m.group()
        nm = num_pat.search(ms)
        cv = 1 if not nm else int(nm.group())
        if unit == "now":
            visited[unit] = True
            continue
        tu = unit + ("s" if unit[-1] != "s" else "")
        info[tu] = cv
        visited[tu] = True
    if not any(visited.values()):
        raise ValueError(
            "Input string not valid. Note: Some locales do not support the week granulairty in Arrow. "
            "If you are attempting to use the week granularity on an unsupported locale, this could be the cause of this error."
        )
    fp = re.compile(fr"^{l.future.format('.*')}$")
    pp = re.compile(fr"^{l.past.format('.*')}$")
    fpm = fp.findall(timestring)
    ppm = pp.findall(timestring)
    if ppm:
        sign = -1
    elif fpm:
        sign = 1
    elif visited["now"]:
        sign = 0
    else:
        raise ValueError(
            "Invalid input String. String does not contain any relative time information. "
            "String should either represent a time in the future or a time in the past. "
            "Ex: 'in 5 seconds' or '5 seconds ago'."
        )
    time_changes = {k: sign * v for k, v in info.items()}
    return ct.shift(**time_changes)"
    },
    {
      "qualname": "arrow/locales.py::Locale.describe",
      "source": "def describe(
    self,
    timeframe: TimeFrameLiteral,
    delta: Union[float, int] = 0,
    only_distance: bool = False,
) -> str:
    """Describes a delta within a timeframe in plain language.

    :param timeframe: a string representing a timeframe.
    :param delta: a quantity representing a delta in a timeframe.
    :param only_distance: return only distance eg: "11 seconds" without "in" or "ago" keywords
    """

    h = self._format_timeframe(timeframe, trunc(delta))
    return h if only_distance else self._format_relative(h, timeframe, delta)"
    },
    {
      "qualname": "arrow/locales.py::Locale.describe_multi",
      "source": "def describe_multi(
    self,
    timeframes: Sequence[Tuple[TimeFrameLiteral, Union[int, float]]],
    only_distance: bool = False,
) -> str:
    """Describes a delta within multiple timeframes in plain language.

    :param timeframes: a list of string, quantity pairs each representing a timeframe and delta.
    :param only_distance: return only distance eg: "2 hours and 11 seconds" without "in" or "ago" keywords
    """

    parts = [self._format_timeframe(tf, trunc(d)) for tf, d in timeframes]
    if self.and_word:
        parts = parts[:-1] + [self.and_word] + parts[-1:]
    h = " ".join(parts)
    return h if only_distance else self._format_relative(h, *timeframes[-1])"
    },
    {
      "qualname": "arrow/locales.py::HebrewLocale._format_timeframe",
      "source": "def _format_timeframe(
    self, timeframe: TimeFrameLiteral, delta: Union[float, int]
) -> str:
    """Hebrew couple of <timeframe> aware"""
    couple = f"2-{timeframe}"
    single = timeframe.rstrip("s")
    if abs(delta) == 2 and couple in self.timeframes:
        key = couple
    elif abs(delta) == 1 and single in self.timeframes:
        key = single
    else:
        key = timeframe

    return self.timeframes[key].format(abs(delta))"
    },
    {
      "qualname": "arrow/locales.py::HebrewLocale.describe_multi",
      "source": "def describe_multi(
    self,
    timeframes: Sequence[Tuple[TimeFrameLiteral, Union[int, float]]],
    only_distance: bool = False,
) -> str:
    """Describes a delta within multiple timeframes in plain language.
    In Hebrew, the and word behaves a bit differently.

    :param timeframes: a list of string, quantity pairs each representing a timeframe and delta.
    :param only_distance: return only distance eg: "2 hours and 11 seconds" without "in" or "ago" keywords
    """

    parts = [self._format_timeframe(tf, trunc(d)) for tf, d in timeframes]
    if len(parts) == 1:
        h = parts[0]
    else:
        h = parts[0] + "".join(", " + p for p in parts[1:-1]) + " " + self.and_word + ("-" if parts[-1][0].isdecimal() else "") + " " + parts[-1]
    if not only_distance:
        h = self._format_relative(h, *timeframes[-1])
    return h"
    },
    {
      "qualname": "arrow/locales.py::MalteseLocale._format_timeframe",
      "source": "def _format_timeframe(
    self, timeframe: TimeFrameLiteral, delta: Union[float, int]
) -> str:
    form = self.timeframes[timeframe]
    delta = abs(delta)
    if isinstance(form, Mapping):
        if delta == 2:
            form = form["dual"]
        else:
            form = form["plural"]

    return form.format(delta)"
    },
    {
      "qualname": "arrow/locales.py::OdiaLocale._ordinal_number",
      "source": "def _ordinal_number(self, n: int) -> str:
    if n > 10 or n == 0:
        return f"{n}ତମ"
    suffix = {1: "ମ", 2: "ୱ", 3: "ୱ", 4: "ର୍ଥ", 5: "ମ", 6: "ୂ", 7: "ମ", 8: "ମ", 9: "ମ", 10: "ମ"}
    return f"{n}{suffix[n]}""
    },
    {
      "qualname": "arrow/locales.py::SerbianLocale._format_timeframe",
      "source": "def _format_timeframe(
    self, timeframe: TimeFrameLiteral, delta: Union[float, int]
) -> str:
    form = self.timeframes[timeframe]
    delta = abs(delta)
    if isinstance(form, Mapping):
        if 1 < delta <= 4:
            form = form["double"]
        else:
            form = form["higher"]

    return form.format(delta)"
    },
    {
      "qualname": "arrow/locales.py::LuxembourgishLocale.describe",
      "source": "def describe(
    self,
    timeframe: TimeFrameLiteral,
    delta: Union[int, float] = 0,
    only_distance: bool = False,
) -> str:

    if not only_distance:
        return super().describe(timeframe, delta, only_distance)

    # Luxembourgish uses a different case without 'in' or 'ago'
    humanized = self.timeframes_only_distance[timeframe].format(trunc(abs(delta)))

    return humanized"
    }
